mapper.select:
SELECT DISTINCT cinema.id, cinema.name, cinema.description, cinema.home_page, cinema.tel, cinema.max_select_seat_count, cinema.full_address, cinema.latitude, cinema.longitude, cinema.postal_code, brand.id as brand_id, brand.name as brand_name,
(fav.id IS NOT NULL) AS is_favorite, ( SELECT COUNT(theater_hall.cinema_id) FROM theater_hall WHERE theater_hall.cinema_id = cinema.id AND theater_hall.deleted = 0 ) AS theater_count,
( 6371000 * acos( cos(radians(#{query.latitude})) * cos(radians(cinema.latitude)) * cos(radians(cinema.longitude) - radians(#{query.longitude})) + sin(radians(#{query.latitude})) * sin(radians(cinema.latitude)) ) ) AS distance
NULL AS distance
FROM cinema LEFT JOIN brand ON cinema.brand_id = brand.id LEFT JOIN user_favorite_cinema fav ON fav.cinema_id = cinema.id AND fav.deleted = 0 AND fav.user_id = #{query.userId}
LEFT JOIN cinema_spec_spec ON cinema.id = cinema_spec_spec.cinema_id
cinema.deleted = 0
AND cinema.name LIKE '%' || #{query.name} || '%'
AND cinema.id = #{query.id}
AND cinema.region_id = #{query.regionId}
AND cinema.prefecture_id = #{query.prefectureId}
AND cinema.city_id = #{query.cityId}
AND cinema.brand_id = #{query.brandId}
AND cinema_spec_spec.spec_id = #{query.specId} AND cinema_spec_spec.deleted = 0
AND cinema.latitude IS NOT NULL AND cinema.longitude IS NOT NULL AND ( 6371000 * acos( cos(radians(#{query.latitude})) * cos(radians(cinema.latitude)) * cos(radians(cinema.longitude) - radians(#{query.longitude})) + sin(radians(#{query.latitude})) * sin(radians(cinema.latitude)) ) ) <= #{query.radius}
ORDER BY
is_favorite DESC, distance ASC

SELECT movie_show_time.id AS id, cinema.id AS cinema_id, cinema.name AS cinema_name, cinema.full_address AS cinema_full_address, cinema.tel as cinema_tel, TO_CHAR(movie_show_time.start_time::date, 'YYYY-MM-DD') AS date, TO_CHAR(movie_show_time.start_time::timestamp, 'HH24:MI') AS start_time, TO_CHAR(movie_show_time.end_time::timestamp, 'HH24:MI') AS end_time, theater_hall.id as theater_hall_id, theater_hall.name as theater_hall_name, -- 把所有规格（IMAX / Dolby / MX4D / TCX 等）按 spec_ids 数组的原顺序拼起来， -- 用「、」分隔；前端按分隔符 split 出多个 chip 展示。 -- 同 getMovieShowTime 一致；不再 LEFT JOIN cinema_spec ON spec_ids[1] 只取首个。 ( SELECT string_agg(cs.name, '、' ORDER BY array_position(movie_show_time.spec_ids, cs.id)) FROM cinema_spec cs WHERE cs.id = ANY(movie_show_time.spec_ids) AND cs.deleted = 0 ) AS spec_name, movie_show_time.subtitle_id, movie_show_time.show_time_tag_id, movie_show_time.movie_version_id, movie_show_time.dimension_type, -- 原版 / 配音版：importer 写入 movie_show_time.dub_version（1=オリジナル版, 2=吹き替え版）。 -- 旧数据若仍走 movie_version.version_code，则作为 fallback。 COALESCE(movie_show_time.dub_version, movie_version.version_code) AS version_code, MIN(movie_show_time.reservation_params_json->>'reservation_url') AS reservation_url, -- 同 reservation_url 同样套路：用 MIN 聚合规避 jsonb 不能直接放 GROUP BY 的限制 MIN(movie_show_time.crawl_raw_json->>'status') AS sale_status FROM movie_show_time LEFT JOIN cinema ON movie_show_time.cinema_id = cinema.id LEFT JOIN theater_hall ON movie_show_time.theater_hall_id = theater_hall."id" LEFT JOIN movie_version ON movie_version.id = movie_show_time.movie_version_id AND movie_version.deleted = 0 WHERE movie_show_time.deleted = 0 AND movie_show_time.cinema_id = #{query.cinemaId} AND movie_show_time.movie_id = #{query.movieId}
AND movie_show_time.re_release_id = #{query.reReleaseId}
AND movie_show_time.re_release_id IS NULL
AND COALESCE(movie_show_time.dub_version, movie_version.version_code) = #{query.versionCode}
AND movie_show_time.start_time::timestamp >= now()
AND TO_CHAR(movie_show_time.start_time::timestamp, 'HH24:MI') >= #{query.startTimeFrom}
AND TO_CHAR(movie_show_time.start_time::timestamp, 'HH24:MI') <= #{query.startTimeTo}
GROUP BY date, movie_show_time.id, cinema.id, cinema.name, cinema.full_address, cinema.tel, movie_show_time.start_time, movie_show_time.end_time, theater_hall.id, theater_hall."name", movie_show_time.spec_ids, movie_show_time.subtitle_id, movie_show_time.show_time_tag_id, movie_show_time.movie_version_id, movie_show_time.dimension_type, movie_show_time.dub_version, movie_version.version_code ORDER BY date, movie_show_time.start_time
